        "시장 구역을 조금 벗어난 주거 지역은 오래된 다세대주택과 빌라가 골목마다 밀집해 있고 외관도 서로 비슷한 경우가 많으므로, 정확한 동·호수 안내가 특히 중요해지는 동네입니다. "
