        "아차산 방면의 언덕 구역은 겨울철에 도로가 결빙되기 쉬워 주의가 필요하며 눈이 내린 날에는 경사 구간 진입에 시간이 평소보다 더 걸릴 수 있으니 양해 부탁드립니다. "
